    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The human-powered devices described by this contract are expressly excluded from vehicles and therefore cannot satisfy the motor-vehicle requirement."
    },
    {
      "class": "ru.bus",
      "verdict": "contradicted",
      "reason": "Passenger-carrying design does not preclude goods use and a goods-built body, and every member meeting those statutory requirements satisfies the supplied truck contract."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a motor vehicle, so the admitting words reach no member."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Every commercial-class member admitted by the motor-vehicle, goods-use and goods-built-body requirements satisfies the quoted ru.truck contract."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The quoted motor-vehicle definition expressly excludes electric bicycles, preventing them from satisfying the truck definition."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The quoted motor-vehicle definition expressly excludes electric scooters, preventing them from satisfying the truck definition."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Any emergency vehicle admitted by the quoted motor-vehicle, goods-use and goods-built-body requirements necessarily satisfies the supplied ru.truck contract."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "Any fire-fighting vehicle admitted by the quoted requirements necessarily has the motor-vehicle and goods-body characteristics specified by the ru.truck contract."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "Every moped meeting the quoted motor-vehicle, goods-use and goods-built-body requirements also meets the supplied ru.truck contract."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The quoted definition admits members of this class only with goods use and a body built for that purpose, which together satisfy the ru.truck contract."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "Any motorcycle admitted by the goods-use and goods-built-body requirements satisfies the supplied ru.truck contract regardless of its wheel configuration."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Every official-service vehicle admitted by the quoted motor-vehicle, goods-use and goods-built-body requirements satisfies the ru.truck contract."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "This contract describes a person rather than a motor vehicle, so the quoted admitting words reach no member."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The cane, animal or accompanying person does not change the contract's pedestrian person into a motor vehicle."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The quoted motor-vehicle definition rules out operation upon rails, matching the on-track equipment described by this contract."
    },
    {
      "class": "ru.school_bus",
      "verdict": "contradicted",
      "reason": "School-child designation does not preclude goods use and a goods-built body, and every member meeting the statutory requirements satisfies the supplied truck contract."
    },
    {
      "class": "ru.taxicab",
      "verdict": "contradicted",
      "reason": "The passenger-for-hire contract does not prohibit goods use or a goods-built body, and every member satisfying the definition also satisfies the supplied truck contract."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "contradicted",
      "reason": "The contract's passenger-service characteristics do not prohibit the statutory goods-use and body characteristics, whose satisfaction also meets the supplied truck contract."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "contradicted",
      "reason": "Every combination admitted by the quoted motor-vehicle, goods-use and goods-built-body requirements necessarily satisfies the supplied truck contract, so variation among other members does not establish unresolvedness."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "contradicted",
      "reason": "Public-transit service does not rule out goods use and a goods-built body, and every member satisfying the definition also satisfies the supplied truck contract."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The contract supplies the motor-vehicle, goods-carrying and purpose-built-body characteristics required by the quoted definition, with no applicable exception removing the class."
    }
  ]
}

